quests[41332] = { id = 41332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascending The Circle", description = "Now, you are more powerful than ever! Truly, you are a druid without equal, {name}.\n\nI sense that Malfurion has arrived. He will certainly want to know of your accomplishments, but first, please walk with me a moment.", progress = "Yes?", completion = "Congratulations, Archdruid {name}.\n\nWe will be counting on you in the days ahead.", objectives = "Accompany Archdruid Greathoof and then speak with Malfurion Stormrage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
