quests[41335] = { id = 41335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elements Call...", description = "Nobundo is right. Conventional tactics will not work against the Legion - the Broken Shore taught us that. We must scour the world for weapons to use against the Legion!\n\nThe Doomhammer is missing and must be recovered. Rehgar and Erunak have some other ideas, as well. Whatever our course, we must act immediately.\n\nSpeak with me to go over your options, but the final decision is yours!", progress = "Have you made your decision yet?", completion = "A good choice. There is no time to lose - let us begin!", objectives = "Speak with Thrall and choose the Artifact you wish to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
