quests[41367] = { id = 41367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priority Delivery", description = "An adventurer of another time has forgotten to loot something big... something that might cause them great emotional strain if not received quickly.\n\nYour destination is Icecrown Citadel, your target the Lich King's corpse. Retrieve the missing item post-haste and deliver it to the stalwart adventurer - he should be somewhere at the Steam Pools in Feralas.\n\nMy assistant will open a portal to deliver you there. Just a moment!", progress = "Hold, peasant. What business have you with the illustrious Johnny Awesome?", completion = "You'd best carry a reason of a higher caliber than that to dare interrupt my time with these buxom beauties.", objectives = "Recover the forgotten loot from the Lich King and find its intended recipient at the Steam Pools in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41368] = { id = 41368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Mail", description = "TO: MADAM GOYA, DALARAN UNDERBELLY\n\nURGENT!\n\nTIME-SENSITIVE! \n\nDELIVER IMMEDIATELY!", progress = "What's this? You are not my usual courier...", completion = "Ah, a bank note. Mr. Stonebrow's payment.\n\nJust in the nick of time it would seem.", objectives = "Deliver the Lost Mail to Madam Goya in Dalaran Underbelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41394] = { id = 41394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Service with a Smile", description = "Oh, simple {race}. Simple, simple {race}.\n\nI did not 'forget' to sweep up those reins from that foolish cakewalk of a knight they call the Lich King. I simply did not bother, as I already received the mighty steed during my raid last week.\n\n<Johnny motions to the horse on his left.>\n\nSince you're here and clearly intrigued by my sweltering greatness, won't you take that superfluous stallion to the assistant resort director in town? My coffers could use a bit of extra lining.", progress = "Do not tarry, {class}. The longer you take, the longer until you may dote on me as one of my many admirers.", completion = "<Johnny raises his arm exaggeratedly, glancing at his naked wrist.>\n\nMy, my, quite the LETHARGIC adventurer, aren't you? That just might cover my repair bills from the many dungeons I've plundered.", objectives = "Sell Invincible's Reins to Gott Weedlespan for Johnny Awesome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41395] = { id = 41395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Due Reward", description = "You have served me well these past few minutes we've spent together - minutes I shall not soon forget.\n\nI believe a reward befitting your unwavering loyalty is in order. You will have the distinct honor of placing Twinkles' favorite toy by his grave in honor of his memory.\n\nPlease, please - save your thanks for Twinkles; it is not every day that we may honor a horse made of STARS.", objectives = "Place Twinkles' favorite toy by his grave at the Sludge Fields in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41397] = { id = 41397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Huge Package", description = "Due to the incredible volume of complaints in recent months we have been barred from delivering s... s...\n\n<The Postmaster holds back tears, pain visible in his eyes.>\n\nSolid stone. We're positively swimming in it - if we can't deliver it then pretty soon we will be overwh-\n\n<The Postmaster's eyes light up suddenly.>\n\nThat's it!\n\nThere is an old Consortium portal not far from here that we could deposit it in with none the wiser!\n\nCan you help, {name}? The stone is extraordinarily heavy.", completion = "Is the deed done?", objectives = "Deliver 1,362 pieces of solid stone to the Ethereal Portal in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41400] = { id = 41400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle: Pandaren Cuisine!" }
quests[41405] = { id = 41405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle: Pandaren Cuisine - Sungshin Ironpaw" }
quests[41406] = { id = 41406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle: Pandaren Cuisine - Torg Slowflame" }
quests[41408] = { id = 41408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle: Pandaren Cuisine - Elling Trias" }
quests[41409] = { id = 41409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timing Is Everything", description = "Can you feel it, {name}? The waters churn with approaching Sashj'tar.\n\nYou must strike now...\n\nLeave me... Find a way to bombard the naga... with the kegs...\n\nProtect... Jandvik...", completion = "Fjolrik died in honor of Jandvik. We will remember his bravery.", objectives = "Ride an Azuregale Paddlefoot and kill 50 Sashj'tar naga using the Sealed Powder Kegs in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41410] = { id = 41410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dry Powder", description = "{name}... I did not expect to see you down here.\n\nThe Sashj'tar are... rallying against Jandvik. I had a plan to... decimate them using these old powder kegs.\n\nThe naga proved more formidable to these old bones than I thought.\n\n<Fjolrik coughs out some blood.>\n\nWe haven't much time... to prepare.", progress = "Move quickly, {name}.", completion = "<Fjolrik looks at you weakly.>\n\nYou made it back in time...", objectives = "Collect 5 Sealed Powder Kegs from the shipwrecks in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41411] = { id = 41411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Mail", description = "TO: MADAM GOYA, DALARAN UNDERBELLY\n\nURGENT!\n\nTIME-SENSITIVE! \n\nDELIVER IMMEDIATELY!", progress = "What's this? You are not my usual courier...", completion = "Ah, a bank note. Mr. Stonebrow's payment.\n\nJust in the nick of time it would seem.", objectives = "Deliver the Lost Mail to Madam Goya in Dalaran Underbelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41412] = { id = 41412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Retreat" }
quests[41413] = { id = 41413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Could Go Wrong?", objectives = "Zen'kiki be excited ta' be learning from da Archdruid!\n\nI be keepin' dis place real nice for ya in return for ye help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41414] = { id = 41414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Deathwing" }
quests[41415] = { id = 41415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Call", description = "I realize we have never met, but you will learn of my order soon enough. For now, pleasantries must wait.\n\nThe Legion has returned to Azeroth stronger than ever, and we need new weapons to fight them.\n\nI have met three individuals here in Dalaran who have leads on ancient artifacts which could prove vital in the battle to come. Acquiring these weapons demands the skills of a master hunter.\n\nSpeak to each of them and decide whom you will aid first.", progress = "Have you chosen a lead to pursue first?", completion = "Any of the three weapons you learned of would be a huge boon in the war against the Legion.\n\nBut your crusade must start with one of them, so you must choose.", objectives = "Investigate leads on three artifact weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41416] = { id = 41416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retake the Skyhorn" }
quests[41420] = { id = 41420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Nightwatcher's Perch" }
quests[41421] = { id = 41421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Nightwatcher's Perch" }
quests[41422] = { id = 41422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Preparations", description = "G'Hanir is... is...\n\n<Mylune wipes her eyes, sniffling.>\n\nCorrupted! The Nightmare has risen from the depths of the dream. It all happened so fast...\n\nI was able to secret the staff here through the dream before it fell fully. It rests for now... but I fear we don't have much time.\n\nYou must prepare to retrieve G'Hanir from the Dream. Draw water from the sacred moonwell on the northern edge of the grove and obtain an ancient's blessing.\n\nQuickly - every moment is precious!", progress = "Are you ready?", completion = "<Mylune's face brightens.>\n\nThen there is still hope!", objectives = "Fill a cup with moonwell water and obtain Leafbeard the Storied's blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41423] = { id = 41423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar Noble District Reward Quest" }
quests[41424] = { id = 41424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar Noble District Heroic Reward Quest" }
quests[41425] = { id = 41425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Foes", description = "The Tidemistress... is filling her ranks with hulking naga... and sea giants.\n\nJandvik cannot withstand... their combined might.\n\nSlaughter them... before they reach its shores...", progress = "The Sashj'tar attacks are relentless.", completion = "The Sashj'tar forces are far greater than I imagined.", objectives = "Kill 6 Sashj'tar Overseers and 6 Trenchwalker Scavengers in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41426] = { id = 41426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Their Will", description = "When the naga brought me down here, I saw many of my vrykul mining the sea floor. They had... squids... attached to their faces.\n\nWhatever those things are, they must be controlling my kin and forcing them to work for the naga.\n\nI do not know what will happen if you remove the squids, but I would rather my vrykul die than be slaves to the naga.\n\nSee me in Jandvik when the deed is done.", completion = "I must express gratitude for the vrykul you have saved this day.", objectives = "Remove Writhing Willbreakers from 6 Possessed Vrykul in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41427] = { id = 41427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Vrekt" }
