quests[41435] = { id = 41435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smooth Leystone Deposits" }
quests[41436] = { id = 41436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Deep Slumber", description = "This bed will be yours for the deep slumber that will usher you into the Dream.\n\nOnce you are comfortable, drink of the moonwater you brought. I will guide you from there.\n\nQuickly, now - with every passing moment G'Hanir slips further into darkness.", progress = "Were you able to retrieve G'Hanir?", completion = "Delving into the Dream with such darkness encroaching is no simple task, one few druids dare attempt, but I'm afraid your journey is far from over.", objectives = "Enter the Emerald Dream and retrieve G'Hanir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
