quests[41448] = { id = 41448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Felslate Deposits" }
quests[41449] = { id = 41449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Dreamer", description = "I'm afraid I can't really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes.\n\nThat's ok, though - Naralex has offered to help!\n\nGo to the very bottom of the Tel'Andu Barrow Den. Naralex is already there setting things up for you.", completion = "My preparations are complete. Are you prepared to enter the Dream?", objectives = "Find Naralex deep within the Tel'Andu Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41451] = { id = 41451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Hrydshal" }
quests[41452] = { id = 41452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feline Frantic", description = "Greetings, stranger.\n\n<Mayruna bows to you.>\n\nWe arrived from Val'Sharah a short time ago with hopes of settling here. Our journey was not easy and we are weary.\n\nThese owlcats have made a mess of our camp, as you can surely see. Would you be so kind as to assist us with cleaning up?\n\nThen perhaps you can help us establish a new moonwell!", progress = "Is everything in its proper place?", completion = "All is in its proper place. We are that much closer to being settled.", objectives = "Organize the camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41453] = { id = 41453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homeward Bounding", description = "The first step to establishing a moonwell is to gain the blessings of the local wildlife. \n\nIt is their good will that enables us to  peacefully coexist, and a moonwell thrives on such energies. Combined with Elune's light, a moonwell can purify its surroundings for years.\n\nTo begin, we must find creatures willing to give their blessing. We can start with these owl-cat creatures.\n\nThey ran while you cleaned, but I saw one lingering just before the bridge. \n\nSee if you can find where it lives!", progress = "Did you bring the little one back with you?", completion = "Well this is an interesting turn of events.", objectives = "Chase the Lost Feathermane Kitten across the bridge and return it to its family.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41454] = { id = 41454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luminous Leystone Outcropping" }
quests[41455] = { id = 41455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleaming Leystone Outcropping" }
quests[41457] = { id = 41457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radiant Leystone Outcropping" }
quests[41458] = { id = 41458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardened Leystone Outcropping" }
quests[41459] = { id = 41459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dense Leystone Outcropping" }
quests[41460] = { id = 41460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Leystone Outcropping" }
quests[41461] = { id = 41461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malevolent Felslate Outcropping" }
quests[41462] = { id = 41462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Has Huge Feet", description = "The Ettin's hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time.\n\nMardranel Forestheart would be interested in this.", completion = "Ahhhh... Well done, I am sure our furry friends here are very thankful for your efforts.", objectives = "Take the Grotesque Ettin Leather to Mardranel Forestheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41463] = { id = 41463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Along the Way", description = "As we retreated from Val'Sharah, our company was briefly separated by a conflict with some satyrs at the border.\n\nOne of our own did not make it here- Mythandros' brother, Kalendros. I would like you to try and find him if you could.\n\nSearch the woods just before the bridge back into Val'Sharah.", completion = "How good of Mayruna to send help. I had nearly lost hope.", objectives = "Locate Kalendros Irongrove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41464] = { id = 41464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Here, Not Now, Not Ever", description = "I cannot, will not, accept what is happening here. My body resists me, but I will stop this.\n\n<He looks at you.> You will stop this.\n\nHere is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar.\n\nStop them. Kill the satyrs, take their horns, drive their points through the totems.\n\nOnly then can we have any hope of reversing this.", progress = "Have you stalled their efforts, {race}?", completion = "I am relieved, though there remains more we must do.", objectives = "Use Satyr Horns to destroy 3 Darkfiend Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41465] = { id = 41465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estate Jewelry: A Braggart's Brooch", description = "Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers.\n\nNaltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city's elite.\n\nI sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station.\n\nMy pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.", progress = "That oaf will undo years of hard work. It is so much easier to fall than it is to climb...", completion = "Ahh, see! I told you it would not tarnish. Now there's nothing linking me to that fool...\n\nWhat's that? A plot to weaken his position? Regardless, the damage has been done. Better safe than sorry.", objectives = "Retrieve Lespin's Brooch from Naltethis Springblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41466] = { id = 41466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estate Jewelry: Haute Claw-ture", description = "An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten.\n\nI was... vain, centuries ago. Desperate to prove myself, I took on a bold commission.\n\nFind him and bring... it... back. You will know what I am talking about when you see it.\n\nHe resides near the villa south of this courtyard.", progress = "He was so passionate, so driven. I saw his vision, created it to his exact specifications. Beautiful filigree and enamel put to a fearsome weapon...", completion = "By the Magistrix, I had forgotten how ugly that thing is. Impeccable workmanship, obviously. Just... ugh. I should melt the whole thing down.", objectives = "Find and retrieve Lespin's 'art' from Mornath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41467] = { id = 41467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Choice We Can Make", description = "Take this torch, {name}. \n\nWe cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations.\n\nIncinerate the root. Only then can we rest easy in Suramar.", completion = "What a disturbing tale!", objectives = "Incinerate the Shaladrassil Root.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41468] = { id = 41468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistress of the Claw", description = "The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian's death his claws were hidden away, safe from any who would use their power for evil.\n\nLea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea.\n\nShe and her Druids of the Claw reside in the Tel'Andu Barrow Den just to the north.", completion = "The Claws of Ursoc?\n\nI thought I'd go the rest of my days without hearing of them again. Is our situation truly so dire? They were sealed away for good reason!", objectives = "Find Lea Stonepaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41469] = { id = 41469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Irongrove Retreat", description = "We have three blessings from the creatures we share this land with.\n\nCombined with a blessing from Elune, the moonwell will watch over this land for years to come.\n\nMeet Mythandros at the retreat. I am sure he would like to include you in the ritual.", completion = "Welcome back. I see we are ready to begin.", objectives = "Seek Mythandros at Irongrove Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41473] = { id = 41473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redhoof the Ancient", description = "While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east.\n\nI believe Mythandros may have found the next creature that may offer us its blessing.\n\nThere is a secluded glade along the river's bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.", completion = "This fine gentleman was just telling me how dearly he loves his forest. Let us assist him!", objectives = "Locate Mythandros and Redhoof the Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41474] = { id = 41474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fertilizing the Future", description = "Like most herbivores, our antlered friends will eat anything green enough to chew. \n\nHowever I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food.\n\nI will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.", progress = "How goes the planting?", completion = "They are looking better fed already!", objectives = "Plant 5 Lush Grass Seeds in piles of Rich Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41475] = { id = 41475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prongs and Fangs", description = "Now, {name}, do not mistake me- I am a druid. I understand that nature has a balance.\n\nPredators must feed, and others will be hunted. I also understand that tampering with such balance has consequences.\n\nThat is why I have taken upon myself to walk this land and perform some... ah... calculations.\n\nSlay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.", progress = "Are you being gentle with your pruning?", completion = "In the end, they will all thrive- for with more Sablehorn, the wolves will eat better in the years to come.", objectives = "Slay 8 Suramar Snarlers and Gloomfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41478] = { id = 41478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Blessing", description = "My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. \n\nNow that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.", completion = "Welcome, {race}.", objectives = "Speak to Solendra Featherdown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41479] = { id = 41479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Adversaries", description = "I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers.\n\nTo earn their blessing, I believe we should clear the way for their return.\n\nSlay the basilisks that have taken more than their fair share of the land, {race}.", completion = "Well done, {race}.", objectives = "Slay 8 Manascale Basilisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41480] = { id = 41480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Managazer", description = "There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave.\n\nWe will use this to our advantage.\n\nSeek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.", progress = "Managazer must perish, {race}.", completion = "Such a gluttonous creature.", objectives = "Slay Managazer, the Basilisk Lord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41481] = { id = 41481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Destroyer" }
