quests[41484] = { id = 41484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Destroyer" }
quests[41485] = { id = 41485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonwhisper Rescue", description = "As a druid I understand that predation happens. Creatures that eat meat must acquire meat.\n\nBut this...\n\n<Solendra gestures angrily toward a nearby petrified nightsaber.>\n\nThis is just sad. Free them, {race}. Take my blessing and free them from this needless torment.", progress = "Have you freed them, {race}?", completion = "I am much relieved, {name}.", objectives = "Free 5 Petrified Nightsabers using Solendra's Gift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
