quests[41493] = { id = 41493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brimstone Destroyer" }
quests[41494] = { id = 41494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eminent Grow-main", description = "You have done very well, {race}. \n\nAll that is left is to combine their blessings into the ritual bundle and imbue the Moonwell. Once that is done, Mayruna will add a little water from a purified Moonwell and this land will be protected so long as we inhabit it.\n\nThis is a momentous occasion, my friend. You bear witness to a sacred rite not often performed in the company of strangers.\n\nI will let you do the honors- simply place the ritual bundle into the sacred waters and we will do the rest.", progress = "You witness history, {race}.", completion = "Your assistance made this all possible. Thank you.", objectives = "Imbue the inert waters with the ritual bundle, then witness the well's creation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41495] = { id = 41495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brilliant Leystone Seams" }
