quests[41498] = { id = 41498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone Basilisks" }
quests[41499] = { id = 41499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squid Out of Water", description = "Toryl told me about those squid creatures that are controlling my brothers.\n\nI have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came.\n\nI do not want any more of my kin to suffer the fate of being controlled by the naga.\n\nFind out where those squids come from and stop them.", completion = "The naga will not be taking any more of my kin!", objectives = "Destroy 5 Willbreaker Incubators in the Sashj'tar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
