quests[41510] = { id = 41510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeroth Needs You", description = "We shaman under your command will aid your efforts against the Legion. You may direct our actions from here.\n\nSeek out Advisor Sevel just to the south and locate the scouting map from which you can direct your followers. We will also indicate on the scouting map various hot-spots around the Broken Isles that require your attention.\n\nAzeroth needs you, Farseer! Visit the scouting map and choose our first point of attack.", completion = "A sound decision, Farseer. Behind me I have opened up an astral portal to Dalaran to help our people move quickly between our base of operations and the Broken Isles. Step through to return to Dalaran. You may always use the portal to travel back here whenever you need to augment your artifact or command your followers.\n\nMay the elements guide you, Farseer.", objectives = "Select your first assault point on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
