quests[41574] = { id = 41574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Thunder", description = "Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield's Rest. It's a dank, sloppy mess adrift in a sea of gloom.\n\nSounds lovely, eh?\n\nI've been workin' with a vrykul guide named Prustaga. She'll help us break the wards keepin' the tomb sealed.\n\nI know what you're thinkin'... vrykul are trouble. But she hasn't taken a swing at me just yet.\n\nHuey'll take us down to the shore. Prustaga's probably found the tomb by now!", progress = "It's a good thing you found my observation relay! It's been missing for at least a thousand years.", completion = "You might feel a bit dizzy after going through that teleporter. The Broken Isles isn't exactly next door, after all.", objectives = "Accompany Grif Wildheart to Shield's Rest Island and track down Titanstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41575] = { id = 41575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsoul Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>", objectives = "Infuse the Beacon with Ancient Mana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
