quests[41606] = { id = 41606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Brytag", description = "<Kell barely manages to speak.>\n\nThat naga witch... has given many of my kin... to the sea giants.\n\nBrytag was... the last one I saw alive.\n\nFind him quickly.", completion = "I do not know who you are, but you are not a sea giant, and that is enough for me.", objectives = "Locate Brytag in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41607] = { id = 41607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Promenade", description = "We must learn much about our long-lost kin if we are to fight them.\n\nWe dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in.\n\nThey have not returned in some time, and we must suspect the worst.\n\nFind them and we shall see what we are up against.", completion = "They are alive? That is good news. Their knowledge of the defenses will be invaluable.", objectives = "Locate the scouts in the Promenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
